  4082	        if (footnotes_enabled) {
  4083	                memset(&doc->footnotes_found, 0x0, sizeof(doc->footnotes_found));
  4084	                memset(&doc->footnotes_used, 0x0, sizeof(doc->footnotes_used));
  4085	        }
  4086	
  4087	        /* first pass: looking for references, copying everything else */
  4088	        beg = 0;
